package com.neu.riketiku.zhanghao;
import static org.assertj.core.api.Assertions.*;import com.neu.riketiku.renzheng.TuXingYanZhengMaFuWu;import com.neu.riketiku.tiku.admin.AdminQuestionIntegrationTestSupport;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(properties="app.auth.captcha.expose-test-code=true") class PasswordRecoveryIntegrationTest extends AdminQuestionIntegrationTestSupport{@Autowired PasswordRecoveryService service;@Autowired TuXingYanZhengMaFuWu captcha;@Autowired JdbcTemplate jdbc;@Autowired PasswordEncoder encoder;
@Test @Transactional void antiEnumerationSinglePendingAndTransactionalResolution(){String suffix=UUID.randomUUID().toString().replace("-","").substring(0,8);jdbc.update("INSERT INTO yong_hu(yong_hu_ming,mi_ma_zhai_yao) VALUES (?,?)","recover"+suffix,"x".repeat(60));long user=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);var unknown=captcha.create(null);var valid=captcha.create(null);assertThat(service.request(new PasswordRecoveryDtos.Request("missing"+suffix,unknown.challengeId(),unknown.testCode())).message()).isEqualTo("如账号有效，密码恢复请求已提交给管理员。");assertThat(service.request(new PasswordRecoveryDtos.Request("recover"+suffix,valid.challengeId(),valid.testCode())).message()).isEqualTo("如账号有效，密码恢复请求已提交给管理员。");var again=captcha.create(null);service.request(new PasswordRecoveryDtos.Request("recover"+suffix,again.challengeId(),again.testCode()));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM mi_ma_chong_zhi_shen_qing WHERE yong_hu_id=?",Integer.class,user)).isEqualTo(1);long request=jdbc.queryForObject("SELECT id FROM mi_ma_chong_zhi_shen_qing WHERE yong_hu_id=?",Long.class,user);service.resolve(request,user);String hash=jdbc.queryForObject("SELECT mi_ma_zhai_yao FROM yong_hu WHERE id=?",String.class,user);assertThat(encoder.matches("a1234567",hash)).isTrue();assertThat(jdbc.queryForObject("SELECT shi_fou_shou_ci_deng_lu FROM yong_hu WHERE id=?",Boolean.class,user)).isFalse();assertThat(service.list().records()).anySatisfy(item->assertThat(item.status()).isEqualTo("RESOLVED"));}}
